import copy, json, re, sys
errs = []
def check(cond, msg):
    print(("PASS " if cond else "FAIL ") + msg)
    if not cond: errs.append(msg)
PATH = "docs/reviews/llm-benchmark/E1b-r6/schema-draft.json"
doc = json.load(open(PATH))
check(doc["draft_version"] == "0.7.0", "schema version 0.7.0")
check(doc["status"] == "DRAFT / NOT EFFECTIVE", "status DRAFT/NOT EFFECTIVE")
def resolve(root, ref):
    if not ref.startswith("#/"):
        raise ValueError("not a local pointer: " + ref)
    node = root
    for raw in ref[2:].split("/"):
        tok = raw.replace("~1", "/").replace("~0", "~")
        if isinstance(node, list):
            if not re.fullmatch(r"0|[1-9][0-9]*", tok):
                raise ValueError("array index expected, got %r in %s" % (tok, ref))
            node = node[int(tok)]
        elif isinstance(node, dict):
            if tok not in node:
                raise ValueError("missing key %r in %s" % (tok, ref))
            node = node[tok]
        else:
            raise ValueError("cannot traverse scalar at %r in %s" % (tok, ref))
    return node
def collect_refs(node, out):
    if isinstance(node, dict):
        for k, v in node.items():
            if k == "$ref" and isinstance(v, str):
                out.append(v)
            else:
                collect_refs(v, out)
    elif isinstance(node, list):
        for v in node:
            collect_refs(v, out)
refs = []
collect_refs(doc, refs)
check(len(refs) > 0, "refs collected: %d" % len(refs))
unresolved, targets = [], {}
for r in refs:
    try:
        t = resolve(doc, r)
        targets[r] = (t.get("def_id"), t.get("def_kind")) if isinstance(t, dict) else ("<scalar>", "")
    except ValueError as e:
        unresolved.append("%s (%s)" % (r, e))
check(not unresolved, "all refs resolve (unresolved=%s)" % (unresolved or []))
for r in sorted(set(refs)):
    print("  RESOLVED", r, "->", targets[r])
bad_pattern = [r for r in set(refs) if re.fullmatch(r"#/fields/[^0-9/][^/]*", r)]
check(not bad_pattern, "no array-mid invalid pointers (found=%s)" % (bad_pattern or []))
for d in ["F1","F2","F3","F4","unscorable_reason","f3_gap","f4_gap","applicability_resolution","inapplicability_reason"]:
    check(d in doc.get("$defs", {}), "$defs has " + d)
    check(doc["$defs"][d].get("def_id") == d, "$defs/%s self-identifies" % d)
SHAPE_KEYS = {"type","values","value","requires","requires_conditional","criterion_ref","reading_values","confidence_values"}
rr = next(f for f in doc["fields"] if f["id"] == "RESPONSE_RATING")
slot = rr["structure"]["slot_schema"]
drift = {k: sorted(set(v) & SHAPE_KEYS) for k, v in slot.items() if isinstance(v, dict) and "$ref" in v}
check(not any(drift.values()), "no duplicate shapes in slot $refs")
thin = {e["id"]: sorted(set(e) & (SHAPE_KEYS | {"output_centered"})) for e in doc["fields"] if e.get("id") in ("F1","F2","F3","F4")}
check(not any(thin.values()), "fields-array F1-F4 carry no shapes")
fps = doc["final_payload_schema"]
check(fps["discriminator"] == "final_scoreable_view" and set(fps["branches"]) == {"final_unscorable","final_scoreable"}, "final_payload_schema discriminator + 2 branches")
fbad = []
for bname, b in fps["branches"].items():
    for fname, f in b.get("fields", {}).items():
        if "$ref" not in f:
            fbad.append("%s.%s: no $ref" % (bname, fname))
check(not fbad, "final branch fields all $ref")
check(set(fps["branches"]["final_unscorable"].get("forbidden", [])) >= {"F1","F2","F3","F4"}, "final unscorable forbids F1-F4")
neg1 = copy.deepcopy(doc)
n1 = next(f for f in neg1["fields"] if f["id"]=="RESPONSE_RATING")["structure"]["slot_schema"]
n1["F1"]["$ref"] = "#/$defs/NOPE"
r1 = []
collect_refs(neg1, r1)
u1 = []
for r in r1:
    try: resolve(neg1, r)
    except ValueError: u1.append(r)
check("#/$defs/NOPE" in u1, "NEGATIVE-A: broken target detected")
neg2 = copy.deepcopy(doc)
n2 = next(f for f in neg2["fields"] if f["id"]=="RESPONSE_RATING")["structure"]["slot_schema"]
n2["F1"]["$ref"] = "#/fields/F1"
r2 = []
collect_refs(neg2, r2)
u2 = []
for r in r2:
    try: resolve(neg2, r)
    except ValueError: u2.append(r)
check("#/fields/F1" in u2, "NEGATIVE-B: array-mid pointer rejected")
live = json.load(open(PATH))
lslot = next(f for f in live["fields"] if f["id"]=="RESPONSE_RATING")["structure"]["slot_schema"]
check(lslot["F1"]["$ref"] == "#/$defs/F1", "live file untouched after negatives")
pb = rr["structure"]["presence_branches"]
check(pb["dal_U_unscorable"]["required_fields"] == ["unscorable_reason"], "R4 Dal U kept")
check(pb["dal_S_scoreable"]["required_fields"] == ["F1","F2"], "R4 Dal S kept")
check(doc["layer_timing"]["response_rating"] == {"layer": "C", "timing": "post_evaluation"}, "R3 layer/timing kept")
f5 = next(f for f in doc["fields"] if f["id"] == "F5")
check("contested" in f5["structure"] and "contested" not in f5["structure"]["resolved_reference"]["fields"], "R3 contested kept")
check(doc["$defs"]["F3"]["criterion_ref"]["binds"] == ["criterion_id", "criterion_version"], "R2 binding kept via $defs")
check("no additional adjudication" in doc["scoreability_final_states"]["both_explicit_unscorable"], "6.2 kept")
check(len(doc["applicability"]["rows"]) == 12, "applicability rows == 12")
blob = open(PATH).read()
for bad in ["probably_benign","probably_concerning","clearly_benign","clearly_concerning","BLIND-","RI-DU-","RI-AM-"]:
    check(bad not in blob, "no human-label/corpus content %r" % bad)
print("LINTER:", "ALL PASS" if not errs else "%d FAILURES" % len(errs))
sys.exit(1 if errs else 0)
